# Mirror of scripts/provider_contracts.py::redact_url (clients are standalone).
# Requires a `?`/`&` prefix, so this masks apikey=/api_key= in URL query
# strings, not a rendered params dict (unreachable today: only
# RequestException text -- which can embed the full request URL -- is
# ever printed here, never a bare params repr()).
_APIKEY_RE = re.compile(r"([?&](?:apikey|api_key)=)[^&\s]+", re.IGNORECASE)


def _redact_key(text: str) -> str:
    """Mask apikey=/api_key= query values so stderr never carries the key."""
    return _APIKEY_RE.sub(r"\1REDACTED", str(text))


# --- FMP endpoint fallback: stable (new users) -> v3 (legacy users) ---


def _et_today(now=None):
    """America/New_York calendar date for provider query windows (issue #427).

    An explicit aware ``now`` wins (deterministic runs/tests); otherwise the
    current instant is converted to America/New_York. ``now`` must be
    timezone-aware when supplied. Fail-closed: missing TZ data raises
    RuntimeError naming the tzdata requirement instead of silently falling
    back to the runner's local clock.
    """
    try:
        tz = ZoneInfo("America/New_York")
    except ZoneInfoNotFoundError as exc:
        raise RuntimeError("America/New_York timezone data is missing; pip install tzdata") from exc
    if now is not None:
        if now.tzinfo is None:
            raise ValueError("now must be timezone-aware")
        return now.astimezone(tz).date()
    return datetime.now(tz).date()


def _stable_hist_url(base, symbols_str, params):
    """stable/historical-price-eod/full?symbol=^GSPC&from=...&to=..."""
    params["symbol"] = symbols_str
    # New stable EOD endpoint ignores `timeseries`; convert to from/to range
    # to bound the payload. Use 2x calendar days to cover N trading days
    # (trading-day/calendar-day ratio ~252/365 ~0.69, so *2 leaves headroom).
    days = params.pop("timeseries", None)
    if days is not None:
        today = _et_today()
        params["from"] = (today - timedelta(days=int(days) * 2)).isoformat()
        params["to"] = today.isoformat()
    return base, params


def _v3_hist_url(base, symbols_str, params):
    """api/v3/historical-price-full/^GSPC?timeseries=80"""
    return f"{base}/{symbols_str}", params


_FMP_ENDPOINTS = {
    "historical": [
        ("https://financialmodelingprep.com/stable/historical-price-eod/full", _stable_hist_url),
        ("https://financialmodelingprep.com/api/v3/historical-price-full", _v3_hist_url),
    ],
}

# Optional Alpaca market-data provider (tradermonty/claude-trading-skills fork).
# Covers the shared price surface only: daily bars ("historical") and latest
# quotes ("quote"). Extension endpoints (earnings calendar, COT, 13F, S&P 500
# constituents, dividends, fundamentals) have no Alpaca equivalent and stay
# FMP-only; those skills degrade to their documented manual/CSV fallbacks.
_ALPACA_DATA_BASE = "https://data.alpaca.markets/v2/stocks"


def _alpaca_symbol(symbol: str) -> str:
    """Map an FMP-style ticker to an Alpaca ticker (BRK-B -> BRK.B)."""
    return symbol.strip().upper().replace("-", ".")


def _alpaca_date_window(days: int) -> tuple[str, str]:
    """Calendar-date window generous enough to contain `days` trading days."""
    today = _et_today()
    start = (today - timedelta(days=int(days) * 2 + 5)).isoformat()
    return start, today.isoformat()


def _fmp_bar_row(bar: dict) -> dict:
    """One Alpaca bar -> one FMP v3 historical row.

    Alpaca bars are fetched unadjusted (adjustment=raw), matching the FMP
    unadjusted `close` contract. `adjClose` is set equal to `close` because
    Alpaca's raw bars carry no dividend adjustment; skills needing total-return
    prices must treat adjClose as raw.
    """
    return {
        "date": (bar.get("t") or "")[:10],
        "open": bar.get("o"),
        "high": bar.get("h"),
        "low": bar.get("l"),
        "close": bar.get("c"),
        "adjClose": bar.get("c"),
        "volume": bar.get("v"),
    }


# --- Optional SQLite market-data cache -------------------------------------
# Enabled only when MARKET_CACHE_PATH points at a cache database. The cache
# is read-through with gap fill for daily bars: hit (enough rows, data
# current) -> serve from the DB with zero network; miss -> fetch only the
# missing symbols from the provider and upsert them. Quotes stay live.
# All cache failures are fail-open: they degrade to a plain network fetch.

def _cache_enabled() -> bool:
    """True when a daily-bar cache database is configured."""
    return bool((os.getenv("MARKET_CACHE_PATH") or "").strip())


def _cache_connect():
    """Open (and initialize) the SQLite daily-bar cache. Failures -> None."""
    try:
        import sqlite3

        path = (os.getenv("MARKET_CACHE_PATH") or "").strip()
        if not path:
            return None
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        conn = sqlite3.connect(path, timeout=5)
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA synchronous=NORMAL")
        conn.execute("PRAGMA busy_timeout=5000")
        conn.execute(
            "CREATE TABLE IF NOT EXISTS daily_bars ("
            "symbol TEXT NOT NULL,"
            "date TEXT NOT NULL,"
            "open REAL, high REAL, low REAL, close REAL, adj_close REAL,"
            "volume REAL,"
            "source TEXT NOT NULL DEFAULT 'alpaca',"
            "fetched_at TEXT NOT NULL,"
            "PRIMARY KEY (symbol, date))"
        )
        conn.commit()
        return conn
    except Exception as exc:  # pragma: no cover - defensive fail-open
        print(f"WARN: market cache disabled ({type(exc).__name__}: {exc})", file=sys.stderr)
        return None


def _cache_expected_latest_date() -> str:
    """Most recent weeknight that should have a completed daily bar (ET).

    Bars land some time after the 16:00 ET close, so today only counts once
    it is 17:00 ET. Holidays self-heal: an expectation of a holiday session
    just fails the freshness check and triggers a cheap refetch.
    """
    try:
        tz = ZoneInfo("America/New_York")
    except ZoneInfoNotFoundError:  # pragma: no cover - defensive
        return ""
    now = datetime.now(tz)
    day = now.date()
    if day.weekday() >= 5 or now.hour < 17:
        day = day - timedelta(days=1)
        while day.weekday() >= 5:
            day = day - timedelta(days=1)
    return day.isoformat()


def _cache_load(conn, symbol: str, start: str, end: str, limit: int):
    """Newest `limit` cached rows for symbol within [start, end], desc order."""
    cursor = conn.execute(
        "SELECT date, open, high, low, close, adj_close, volume FROM daily_bars"
        " WHERE symbol = ? AND date >= ? AND date <= ?"
        " ORDER BY date DESC LIMIT ?",
        (symbol, start, end, int(limit)),
    )
    return cursor.fetchall()


def _cache_store(conn, symbol: str, rows: list[dict]) -> None:
    """Upsert one symbol's daily-bar rows (newest-first or oldest-first)."""
    from datetime import datetime as _dt

    stamp = _dt.now(tz=ZoneInfo("UTC")).isoformat(timespec="seconds")
    payload = [
        (
            symbol,
            row["date"],
            row.get("open"),
            row.get("high"),
            row.get("low"),
            row.get("close"),
            row.get("adjClose"),
            row.get("volume"),
            "alpaca",
            stamp,
        )
        for row in rows
        if row.get("date")
    ]
    if payload:
        conn.executemany(
            "INSERT OR REPLACE INTO daily_bars"
            " (symbol, date, open, high, low, close, adj_close, volume,"
            "  source, fetched_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            payload,
        )
        conn.commit()


def _cache_hit(conn, symbol: str, start: str, end: str, days: int):
    """Return newest `days` cached rows when cache coverage is complete.

    A hit needs at least `days` rows in the window AND a newest bar at or
    after the expected latest completed session. Otherwise returns None and
    the caller fetches from the provider.
    """
    expected = _cache_expected_latest_date()
    if not expected:
        return None
    rows = _cache_load(conn, symbol, start, end, int(days))
    if len(rows) < int(days) or rows[0][0] < expected:
        return None

    def _row(rec):
        return {
            "date": rec[0],
            "open": rec[1],
            "high": rec[2],
            "low": rec[3],
            "close": rec[4],
            "adjClose": rec[5],
            "volume": rec[6],
        }

    return [_row(rec) for rec in rows]


def _normalize_eod_flat_list(data, symbols_str: str, limit: Optional[int] = None):
    """Convert stable/historical-price-eod/full flat list to v3-compatible dict.

    Input  : [{"symbol": "SPY", "date": "...", "open": ..., ...}, ...]
    Output : {"symbol": "SPY", "historical": [{"date": ..., "open": ..., ...}, ...]}

    Returns the input unchanged if not a list (passthrough for v3 dict /
    historicalStockList responses). Returns None when no row matches the
    requested symbol; the caller will record the failure and try the next
    endpoint.

    If `limit` is provided (the original `timeseries=N` request), the
    `historical` list is truncated to the first `limit` entries. The new
    EOD endpoint ignores `timeseries` and returns the full available history,
    so the caller's date-range bounding plus this truncation together preserve
    the legacy "most-recent N rows" contract. Truncation assumes descending
    date order, which the FMP EOD endpoint provides (verified live).

    Note: empty list ``[]`` does not reach this normalizer because the caller's
    ``if not data: continue`` falsy check handles it earlier in
    ``_request_with_fallback``.
    """
    if not isinstance(data, list):
        return data
    if not data:
        return None
    norm_target = symbols_str.replace("-", ".")
    matched_symbol = None
    historical = []
    for row in data:
        if not isinstance(row, dict):
            continue
        # Be permissive: single-symbol endpoint may omit per-row "symbol".
        # Treat missing symbol as belonging to the requested symbols_str.
        row_sym = row.get("symbol") or symbols_str
        if row_sym.replace("-", ".") != norm_target:
            continue
        matched_symbol = matched_symbol or row_sym
        historical.append({k: v for k, v in row.items() if k != "symbol"})
    if not historical:
        return None
    if limit is not None and limit > 0:
        historical = historical[:limit]
    return {"symbol": matched_symbol or symbols_str, "historical": historical}


class FMPClient:
    """Client for Financial Modeling Prep API with rate limiting and caching"""

    BASE_URL = "https://financialmodelingprep.com/api/v3"
    ALPACA_DATA_BASE = _ALPACA_DATA_BASE
    RATE_LIMIT_DELAY = 0.3  # 300ms between requests

    _ENDPOINT_FAILURE_THRESHOLD = 3  # disable endpoint after N consecutive failures

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = (api_key or os.getenv("FMP_API_KEY") or "").strip()
        self.provider = self._resolve_provider()
        if self.provider == "fmp" and not self.api_key:
            raise ValueError(
                "API key required. Set FMP_API_KEY environment variable, or set "
                "ALPACA_API_KEY and ALPACA_SECRET_KEY to use the Alpaca "
                "market-data provider (or pass api_key parameter)."
            )
        self.alpaca_feed = (os.getenv("ALPACA_DATA_FEED") or "iex").strip().lower()
        self.session = requests.Session()
        self.session.headers.update({"apikey": self.api_key})
        self.cache = {}
        self.last_call_time = 0
        self.rate_limit_reached = False
        self.retry_count = 0
        self.max_retries = 1
        self.api_calls_made = 0
        # Circuit breaker: track consecutive failures per endpoint URL prefix
        self._endpoint_failures: dict[str, int] = {}
        self._disabled_endpoints: set[str] = set()
        # Most recent transport-level failure reason; set by _rate_limited_get
        # so _request_with_fallback can surface suppressed errors even when
        # an endpoint was called with quiet=True.
        self._last_error: Optional[str] = None

    def _redact_secret(self, text) -> str:
        """Mask raw and URL-encoded key echoes before diagnostics are truncated."""
        from urllib.parse import quote, quote_plus

        text = _redact_key(text)
        if not self.api_key:
            return text
        patterns = {re.escape(self.api_key)}
        for encoded in (quote(self.api_key, safe=""), quote_plus(self.api_key, safe="")):
            # Percent triplets are case-insensitive; the key's letters are not.
            parts = re.split(r"(%[0-9A-Fa-f]{2})", encoded)
            patterns.add(
                "".join(
                    "(?i:" + re.escape(part) + ")"
                    if re.fullmatch(r"%[0-9A-Fa-f]{2}", part)
                    else re.escape(part)
                    for part in parts
                )
            )
        # One pass prevents a short key from matching the replacement marker.
        return re.sub("|".join(sorted(patterns, key=len, reverse=True)), "***REDACTED***", text)

    def _resolve_provider(self) -> str:
        """Resolve the market-data provider for this client instance.

        Priority: explicit ``DATA_SOURCE`` env (``alpaca`` / ``fmp``), else
        auto-detect — Alpaca when ALPACA_API_KEY + ALPACA_SECRET_KEY are both
        set, else FMP (which then requires FMP_API_KEY).
        """
        explicit = (os.getenv("DATA_SOURCE") or "").strip().lower()
        if explicit in ("alpaca", "fmp"):
            return explicit
        if (
            os.getenv("ALPACA_API_KEY", "").strip()
            and os.getenv("ALPACA_SECRET_KEY", "").strip()
        ):
            return "alpaca"
        return "fmp"

    def _alpaca_fetch(self, endpoint_key, symbols_str, params) -> Optional[object]:
        """Route an endpoint through Alpaca; returns already-v3-shaped data or None.

        Only the shared price surface is supported: "historical" (daily bars)
        and "quote" (latest snapshot). Any other endpoint_key returns None so
        the caller falls back to (or fails loudly on) the FMP chain.
        """
        if endpoint_key == "historical":
            timeseries = params.get("timeseries") if isinstance(params, dict) else None
            return self._alpaca_historical(symbols_str, timeseries)
        if endpoint_key == "quote":
            return self._alpaca_quote(symbols_str)
        return None

    def _alpaca_get(self, path: str, params: dict) -> Optional[dict]:
        """Rate-limited authenticated GET against the Alpaca market-data v2 API."""
        key = (os.getenv("ALPACA_API_KEY") or "").strip()
        secret = (os.getenv("ALPACA_SECRET_KEY") or "").strip()
        if not key or not secret:
            self._last_error = "ALPACA_API_KEY / ALPACA_SECRET_KEY not set"
            return None
        self._last_error = None
        elapsed = time.time() - self.last_call_time
        if elapsed < self.RATE_LIMIT_DELAY:
            time.sleep(self.RATE_LIMIT_DELAY - elapsed)
        self.last_call_time = time.time()
        self.api_calls_made += 1
        token = base64.b64encode(f"{key}:{secret}".encode()).decode()
        try:
            response = self.session.get(
                f"{self.ALPACA_DATA_BASE}/{path}",
                params=params,
                headers={"Authorization": f"Basic {token}"},
                timeout=30,
            )
        except requests.exceptions.RequestException as e:
            redacted = self._redact_secret(str(e))
            self._last_error = f"request exception: {redacted}"
            print(f"ERROR: Request exception: {redacted}", file=sys.stderr)
            return None
        if response.status_code != 200:
            body = self._redact_secret((response.text or "")[:200])
            self._last_error = f"HTTP {response.status_code} - {body}"
            print(f"ERROR: Alpaca request failed: {self._last_error}", file=sys.stderr)
            return None
        try:
            return response.json()
        except ValueError as e:
            self._last_error = f"invalid JSON response: {e}"
            return None

    def _alpaca_historical(self, symbols_str: str, timeseries) -> Optional[dict]:
        """Alpaca daily bars -> FMP v3 shape, rows most-recent-first.

        Result rows carry the FMP `adjClose` field set equal to the raw close
        (Alpaca raw bars carry no dividend adjustment — see _fmp_bar_row).
        """
        alpaca_syms = [_alpaca_symbol(s) for s in symbols_str.split(",") if s.strip()]
        supported = [s for s in alpaca_syms if not s.startswith("^")]
        if not supported:
            self._last_error = f"Alpaca has no data for index symbols: {symbols_str}"
            return None
        try:
            days = int(timeseries) if timeseries is not None else 730
        except (TypeError, ValueError):
            days = 730
        if days <= 0:
            days = 730
        start, end = _alpaca_date_window(days)
        rows_by_symbol: dict[str, dict] = {}

        # Read-through cache: symbols fully covered by MARKET_CACHE_PATH data
        # come back with zero network calls; fetch only the uncovered gap set.
        conn = _cache_connect() if _cache_enabled() else None
        cached_ok: dict[str, list[dict]] = {}
        if conn is not None:
            try:
                for sym in supported:
                    hit = _cache_hit(conn, sym, start, end, days)
                    if hit:
                        cached_ok[sym] = hit
            except Exception as exc:  # pragma: no cover - defensive fail-open
                print(
                    f"WARN: market cache read failed ({type(exc).__name__}: {exc})",
                    file=sys.stderr,
                )
                cached_ok = {}
        gaps = [s for s in supported if s not in cached_ok]
        if gaps:
            page_token = None
            for _ in range(20):
                params = {
                    "symbols": ",".join(gaps),
                    "timeframe": "1Day",
                    "start": start,
                    "end": end,
                    "limit": "10000",
                    "adjustment": "raw",
                    "feed": self.alpaca_feed,
                }
                if page_token:
                    params["page_token"] = page_token
                data = self._alpaca_get("bars", params)
                if not data:
                    if not cached_ok:
                        return None
                    break  # serve the covered symbols, record the error
                for sym, bars in (data.get("bars") or {}).items():
                    by_date = rows_by_symbol.setdefault(sym, {})
                    for bar in bars or []:
                        by_date[(bar.get("t") or "")[:10]] = _fmp_bar_row(bar)
                page_token = data.get("next_page_token")
                if not page_token:
                    break
            if conn is not None and rows_by_symbol:
                try:
                    for sym, by_date in rows_by_symbol.items():
                        _cache_store(conn, sym, list(by_date.values()))
                except Exception as exc:  # pragma: no cover - defensive
                    print(
                        f"WARN: market cache write failed ({type(exc).__name__}: {exc})",
                        file=sys.stderr,
                    )

        def _ordered(sym: str) -> list[dict]:
            if sym in cached_ok:
                rows = list(cached_ok[sym])
            elif rows_by_symbol.get(sym):
                rows = [rows_by_symbol[sym][d] for d in sorted(rows_by_symbol[sym], reverse=True)]
            else:
                rows = []
            # FMP `timeseries=N` returns exactly the most-recent N rows; the
            # calendar window overprovisions ~2x, so truncate to the contract.
            if rows and timeseries is not None and int(days) > 0:
                rows = rows[: int(days)]
            return rows

        if len(symbols_str.split(",")) == 1:
            historical = _ordered(supported[0])
            if not historical:
                self._last_error = (
                    f"Alpaca returned no bars for {symbols_str} "
                    f"(feed={self.alpaca_feed})"
                )
                return None
            return {"symbol": symbols_str, "historical": historical}
        batch = []
        for sym in supported:
            if rows_by_symbol.get(sym):
                batch.append(
                    {"symbol": sym.replace(".", "-"), "historical": _ordered(sym)}
                )
        return {"historicalStockList": batch} or None

    def _alpaca_quote(self, symbols_str: str) -> Optional[list[dict]]:
        """Alpaca snapshots -> FMP `quote` list shape (latest prices)."""
        alpaca_syms = [_alpaca_symbol(s) for s in symbols_str.split(",") if s.strip()]
        supported = [s for s in alpaca_syms if not s.startswith("^")]
        if not supported:
            self._last_error = f"Alpaca has no data for index symbols: {symbols_str}"
            return None
        data = self._alpaca_get(
            "snapshots", {"symbols": ",".join(supported), "feed": self.alpaca_feed}
        )
        if not data:
            return None
        quotes = []
        for sym in supported:
            snap = data.get(sym) or {}
            daily = snap.get("dailyBar") or {}
            prev = snap.get("prevDailyBar") or {}
            trade = snap.get("latestTrade") or {}
            price = trade.get("p") or daily.get("c")
            prev_close = prev.get("c")
            if price is None:
                continue
            quote = {
                "symbol": sym.replace(".", "-"),
                "price": price,
                "open": daily.get("o"),
                "dayHigh": daily.get("h"),
                "dayLow": daily.get("l"),
                "previousClose": prev_close,
                "volume": daily.get("v"),
                "timestamp": trade.get("t") or daily.get("t"),
            }
            if prev_close:
                change = price - prev_close
                quote["change"] = change
                quote["changesPercentage"] = change / prev_close * 100.0
            quotes.append(quote)
        return quotes or None

    def _rate_limited_get(
        self,
        url: str,
        params: Optional[dict] = None,
        quiet: bool = False,
        *,
        _json_retry: bool = True,
        _rate_retry: int = 0,
    ) -> Optional[dict]:
        self._last_error = None
        self.retry_count = _rate_retry
        if self.rate_limit_reached:
            self._last_error = "daily rate limit already reached"
            return None

        if params is None:
            params = {}

        elapsed = time.time() - self.last_call_time
        if elapsed < self.RATE_LIMIT_DELAY:
            time.sleep(self.RATE_LIMIT_DELAY - elapsed)

        self.last_call_time = time.time()
        self.api_calls_made += 1
        try:
            response = self.session.get(url, params=params, timeout=30)
            if response.status_code == 200:
                self.retry_count = 0
                try:
                    data = response.json()
                except ValueError as e:
                    # Malformed 200 body: retry once per call chain, then fail
                    # soft with a redacted reason instead of raising. The retry
                    # adds no backoff beyond the normal rate-limit delay and
                    # costs one extra API call (counts against any budget).
                    msg = self._redact_secret(f"invalid JSON response: {e}")
                    if _json_retry:
                        if not quiet:
                            print(f"WARNING: {msg}; retrying once", file=sys.stderr)
                        return self._rate_limited_get(url, params, quiet=quiet, _json_retry=False)
                    self._last_error = msg
                    if not quiet:
                        print(f"ERROR: {msg}", file=sys.stderr)
                    return None
                return data
            elif response.status_code == 429:
                self.retry_count += 1
                if self.retry_count <= self.max_retries:
                    print("WARNING: Rate limit exceeded. Waiting 60 seconds...", file=sys.stderr)
                    time.sleep(60)
                    return self._rate_limited_get(
                        url,
                        params,
                        quiet=quiet,
                        _json_retry=_json_retry,
                        _rate_retry=self.retry_count,
                    )
                else:
                    self._last_error = "HTTP 429 (daily rate limit)"
                    print("ERROR: Daily API rate limit reached.", file=sys.stderr)
                    self.rate_limit_reached = True
                    return None
            else:
                body = self._redact_secret(response.text)[:200]
                msg = self._redact_secret(f"HTTP {response.status_code} - {body}")
                self._last_error = msg
                if not quiet:
                    print(
                        f"ERROR: API request failed: {msg}",
                        file=sys.stderr,
                    )
                return None
        except requests.exceptions.RequestException as e:
            redacted = self._redact_secret(str(e))
            self._last_error = f"request exception: {redacted}"
            print(f"ERROR: Request exception: {redacted}", file=sys.stderr)
            return None

    def _request_with_fallback(self, endpoint_key, symbols_str, extra_params=None):
        """Try stable endpoint first, fall back to v3 for legacy users.

        Returns parsed JSON in v3-compatible shape, or None if all fail.
        Non-last endpoints are called with quiet=True so the user isn't
        alarmed by an expected stable failure when v3 will catch it — but
        when a non-last endpoint DOES fail, a WARN line is emitted explaining
        why we're falling back. Otherwise users only see the (often misleading)
        last-endpoint error and have no clue what really went wrong.
        """
        params = dict(extra_params) if extra_params else {}
        endpoints = _FMP_ENDPOINTS[endpoint_key]
        is_single = "," not in symbols_str

        # Alpaca-first provider: when resolved (auto-detected from Alpaca keys
        # or forced via DATA_SOURCE=alpaca), serve the shared price surface
        # from Alpaca before touching any FMP endpoint. On Alpaca failure,
        # fall through to FMP when a key exists; otherwise fail fast with a
        # clear message instead of burning three 401s on the FMP chain.
        if self.provider == "alpaca":
            alpaca_data = self._alpaca_fetch(endpoint_key, symbols_str, params)
            if alpaca_data is not None:
                return alpaca_data
            if not self.api_key:
                print(
                    "ERROR: Alpaca market data unavailable for "
                    f"'{endpoint_key}' ({self._last_error}) and no FMP_API_KEY "
                    "fallback is configured.",
                    file=sys.stderr,
                )
                return None
            print(
                "WARN: Alpaca provider unavailable for "
                f"'{endpoint_key}' ({self._last_error}); falling back to FMP",
                file=sys.stderr,
            )

        for i, (base_url, url_builder) in enumerate(endpoints):
            # Circuit breaker: skip endpoints with too many consecutive failures
            if base_url in self._disabled_endpoints:
                continue

            url, final_params = url_builder(base_url, symbols_str, dict(params))
            is_last = i == len(endpoints) - 1
            data = self._rate_limited_get(url, final_params, quiet=not is_last)
            if not data:  # falsy (None, [], {}) — try next endpoint
                if data is None:
                    self._record_endpoint_failure(base_url)
                else:
                    self._endpoint_failures[base_url] = 0
                self._warn_fallback(base_url, is_last, self._last_error)
                continue

            # Normalize new stable EOD flat-list shape to v3-compatible dict.
            # No-op for v3 dict / historicalStockList responses.
            # `timeseries` (original request) is passed as `limit` so the
            # EOD endpoint's full-history response is truncated to the
            # legacy "most-recent N rows" contract.
            if endpoint_key == "historical":
                limit = params.get("timeseries") if isinstance(params, dict) else None
                data = _normalize_eod_flat_list(data, symbols_str, limit=limit)
                if not data:
                    self._record_endpoint_failure(base_url)
                    self._warn_fallback(
                        base_url,
                        is_last,
                        f"response had no rows matching '{symbols_str}'",
                    )
                    continue

            # Shape validation: reject truthy-but-wrong-shape responses
            valid = True
            shape_issue: Optional[str] = None
            if endpoint_key == "historical":
                if not isinstance(data, dict):
                    valid = False
                    shape_issue = "expected dict"
                elif "historicalStockList" in data:
                    # stable batch format -> v3 single format (exact match only)
                    norm = symbols_str.replace("-", ".")
                    found = None
                    for entry in data["historicalStockList"]:
                        if entry.get("symbol", "").replace("-", ".") == norm:
                            found = {
                                "symbol": entry.get("symbol"),
                                "historical": entry.get("historical", []),
                            }
                            break
                    if found:
                        self._endpoint_failures[base_url] = 0
                        return found
                    valid = False
                    shape_issue = f"'{symbols_str}' not in historicalStockList"
                elif "historical" not in data:
                    valid = False
                    shape_issue = "missing 'historical' key"
                elif is_single and data.get("symbol"):
                    if data["symbol"].replace("-", ".") != symbols_str.replace("-", "."):
                        valid = False
                        shape_issue = (
                            f"response symbol '{data['symbol']}' != requested '{symbols_str}'"
                        )

            if valid:
                self._endpoint_failures[base_url] = 0
                return data
            self._record_endpoint_failure(base_url)
            self._warn_fallback(base_url, is_last, shape_issue or "unexpected response shape")
        return None

    def _warn_fallback(self, base_url: str, is_last: bool, reason: Optional[str]) -> None:
        """Emit a WARN line so users see why a non-last endpoint failed and the
        client is falling back. No-op when the failing endpoint is the last one
        (its error was already printed by _rate_limited_get with quiet=False)."""
        if is_last or not reason:
            return
        print(
            f"WARN: {base_url} failed ({reason}); falling back to next endpoint",
            file=sys.stderr,
        )

    def _record_endpoint_failure(self, base_url: str) -> None:
        """Track consecutive failures and disable endpoint after threshold."""
        failures = self._endpoint_failures.get(base_url, 0) + 1
        self._endpoint_failures[base_url] = failures
        if failures >= self._ENDPOINT_FAILURE_THRESHOLD:
            self._disabled_endpoints.add(base_url)

    # -- COT surface (cot-contrarian-detector, Issue #495 Batch A) ------------

    # Value-based + pattern-based apikey redaction for (data, error) results.
    # Mirrors the script's own defense-in-depth: headers keep the key out of
    # URLs, but a 4xx body can echo a *bare* key with no "apikey" marker, so
    # the client's own _redact_key alone is NOT sufficient here (#357 class).
    # These literals are static patterns — no live response data flows into
    # them.

    _COT_APIKEY_PATTERNS = (
        re.compile(r"apikey\s*=\s*[^&\s'\"]+", re.IGNORECASE),
        re.compile(r'"apikey"\s*:\s*"[^"]*"', re.IGNORECASE),
        re.compile(r"'apikey'\s*:\s*'[^']*'", re.IGNORECASE),
        re.compile(r"apikey%3d[^&\s'\"]+", re.IGNORECASE),
    )

    def _cot_redact(self, text: Optional[str]) -> Optional[str]:
        """Redact the API key from an error string (value + pattern layers)."""
        if not text:
            return text
        if self.api_key:
            text = text.replace(self.api_key, "***REDACTED***")
        for pattern in self._COT_APIKEY_PATTERNS:
            text = pattern.sub("apikey=***REDACTED***", text)
        return text

    def _cot_error(self) -> Optional[str]:
        """Build a redacted error string from the last transport status."""
        return self._cot_redact(self._last_error)

    def get_market_list(self) -> list[dict]:
        """Fetch every COT-covered market: [{"symbol","name"}, ...].

        Contract preserved from the hand-rolled ``CotClient``: failures
        raise ``RuntimeError("Failed to fetch COT market list: <reason>")``
        so ``resolve_universe`` can't continue on a silent empty list.
        """
        url = "https://financialmodelingprep.com/stable/commitment-of-traders-list"
        data = self._rate_limited_get(url, params={}, quiet=True)
        error = self._cot_error()
        if data is None:
            raise RuntimeError(f"Failed to fetch COT market list: {error}")
        return data if isinstance(data, list) else []

    def get_report(
        self, symbol: str, from_date: str, to_date: str
    ) -> tuple[list[dict], Optional[str]]:
        """Fetch raw legacy-format COT report rows for one symbol.

        Returns ``(rows, None)`` on success and ``([], <redacted reason>)``
        on failure — the ``(data, error)`` contract the script's
        ``analyze_market`` and the "Skipped Markets" report section consume.
        """
        url = "https://financialmodelingprep.com/stable/commitment-of-traders-report"
        data = self._rate_limited_get(
            url, params={"symbol": symbol, "from": from_date, "to": to_date}, quiet=True
        )
        error = self._cot_error()
        if error is not None:
            # Surface the failure without the client's generic print (this
            # surface feeds a user-visible "Skipped Markets" reason).
            print(f"WARN: {error}", file=sys.stderr)
            return [], error
        return data if isinstance(data, list) else [], None

    def get_historical_prices(self, symbol: str, days: int = 90) -> Optional[dict]:
        """Fetch historical daily OHLCV data.

        Args:
            symbol: Stock symbol
            days: Number of trading days to fetch

        Returns:
            Dict with 'symbol' and 'historical' keys, where 'historical' is a
            list of price dicts (most-recent-first) with: date, open, high, low,
            close, adjClose, volume
        """
        cache_key = f"prices_{symbol}_{days}"
        if cache_key in self.cache:
            return self.cache[cache_key]

        data = self._request_with_fallback("historical", symbol, {"timeseries": days})
        if data:
            self.cache[cache_key] = data
        return data

    def get_api_stats(self) -> dict:
        """Return API usage statistics."""
        return {
            "cache_entries": len(self.cache),
            "api_calls_made": self.api_calls_made,
            "rate_limit_reached": self.rate_limit_reached,
        }
